 {page==='transaction-filters'?<><PageHead title="فیلتر تراکنش‌ها" desc="فیلترهای دلخواهت را انتخاب کن و ثبت را بزن."/><form className="transaction-filter-flow" onSubmit={e=>{e.preventDefault();setKind(draftFilters.kind);setCategoryFilter(draftFilters.category);setMember(draftFilters.member);setAccountFilter(draftFilters.account);goBack()}}><Surface as="div" className="filter-panel"><Select label="نوع تراکنش" value={draftFilters.kind} onValueChange={kind=>setDraftFilters(d=>({...d,kind}))} options={['همه','هزینه','درآمد','انتقال','پس‌انداز']}/><Select label="دسته‌بندی" value={draftFilters.category} onValueChange={category=>setDraftFilters(d=>({...d,category}))} options={['همه',...new Set([...categories,...visible.map(t=>t.category)])]}/><Select label="عضو" value={draftFilters.member} onValueChange={member=>setDraftFilters(d=>({...d,member}))} options={['همه',...membersOf(data).map(m=>m.id)]}/><Select label="حساب" value={draftFilters.account} onValueChange={account=>setDraftFilters(d=>({...d,account}))} options={['همه',...data.accounts.map(a=>a.name)]}/></Surface><ActionFooter className="filter-submit app-action-footer"><Action variant="default" type="submit" className="primary">ثبت فیلترها</Action></ActionFooter></form></>:null}
